'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{chromium}=require('playwright-core');
const html=fs.readFileSync(path.join(__dirname,'..','audit-google-auto.html'),'utf8'),executablePath=process.env.CHROMIUM_PATH;
async function setup(browser,rows,viewport={width:390,height:844}){const context=await browser.newContext({viewport,isMobile:viewport.width<700,hasTouch:viewport.width<700}),page=await context.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));await page.route('https://mapping.test/**',r=>r.fulfill({status:200,contentType:'text/html; charset=utf-8',body:html}));await page.goto('https://mapping.test/');await page.evaluate(rows=>{document.getElementById('projectMeta').hidden=true;document.body.classList.remove('meta-stage-active');SHEET_CFG.company='شرکت آزمایشی';SHEET_CFG.year='۱۴۰۴';currentHeaders=['x'];FULL_ROWS=[];ACCOUNT_ROWS=rows;gotoModule('mainWorkpaper');},rows);return {page,context,errors};}
const ledger=[
 {'نوع سند':'ابتدای سال','کد حساب کل':'10','عنوان حساب کل':'موجودی نقد','کد حساب معین':'11','عنوان حساب معین':'بانک الف','بدهکار':'60','بستانکار':''},
 {'نوع سند':'ابتدای سال','کد حساب کل':'10','عنوان حساب کل':'موجودی نقد','کد حساب معین':'12','عنوان حساب معین':'بانک ب','بدهکار':'40','بستانکار':''},
 {'نوع سند':'ابتدای سال','کد حساب کل':'20','عنوان حساب کل':'حساب ناشناخته','کد حساب معین':'21','عنوان حساب معین':'الف','بدهکار':'','بستانکار':'100'},
 {'نوع سند':'ابتدای سال','کد حساب کل':'30','عنوان حساب کل':'حساب بی‌مانده','کد حساب معین':'31','عنوان حساب معین':'ب','بدهکار':'0','بستانکار':''}
];
async function assign(page,code,dest){await page.locator(`[data-map-major="${code}"]`).click();await page.locator('#mwMapDestination').selectOption(dest);await page.locator('#mwMapSave').click();}
async function complete(page){await assign(page,'10','A-70|1|5');await assign(page,'20','A-71|2|0');await assign(page,'30','A-70|1|3');await page.locator('#mwMapFinish').click();await page.locator('#mwPreview .mw-paper').first().waitFor();}
async function choose(page,name,k,minor){await page.locator(`[data-class-open="${name}"]`).click();await page.locator('#mwClassDialog [data-class-clear]').click();await page.locator(`#mwClassDialog [data-class-row-expand='${JSON.stringify(['hier',[0,k]])}']`).dblclick();await page.locator(`#mwClassDialog [data-class-select='${JSON.stringify([k,minor])}']`).check();await page.locator('#mwClassDialog [data-class-confirm]').click();}
test('mandatory GL wizard keeps suggestions unconfirmed, allows search and gates all workpapers', {skip:!executablePath&&'Set CHROMIUM_PATH'},async()=>{const browser=await chromium.launch({executablePath,args:['--no-sandbox','--disable-dev-shm-usage']});try{const {page,context,errors}=await setup(browser,ledger);await page.evaluate(()=>document.fonts.ready);const raw=await page.evaluate(()=>JSON.stringify(ACCOUNT_ROWS));assert(await page.locator('#mwMapTitle').isVisible());assert.equal(await page.locator('#mwPreview').count(),0);assert.equal(await page.locator('#mwClassOpen').count(),0);assert(await page.locator('#mwMapFinish').isDisabled());assert.match(await page.locator('#mwMapProgress').innerText(),/۰ از ۳/);assert(await page.locator('#mwMapSuggest').isVisible());assert.equal(await page.locator('#mwMapTopicSearch').count(),0);assert.equal(await page.locator('#mwMapDestination option[value="A-70|1|5"]').count(),1);await page.locator('#mwMapSuggest').click();assert.equal(await page.locator('#mwMapDestination').inputValue(),'A-70|1|5');assert.match(await page.locator('#mwMapProgress').innerText(),/۰ از ۳/);await page.locator('#mwMapSave').click();assert.match(await page.locator('#mwMapProgress').innerText(),/۱ از ۳/);await page.locator('#mwMapSearch').fill('بی مانده');assert.equal(await page.locator('[data-map-major]').count(),1);assert.equal(await page.locator('[data-map-major="30"]').count(),1);await page.locator('#mwMapSearch').fill('');await assign(page,'20','A-71|2|0');assert(await page.locator('#mwMapFinish').isDisabled(),'a zero-balance account also must be mapped');await assign(page,'30','A-70|1|3');assert(await page.locator('#mwMapFinish').isEnabled());await page.locator('#mwMapFinish').click();await page.locator('[data-mw-view="A-70"]').click();const cash=page.locator('[data-mw-row="A-70|1|5"]');assert.equal(await cash.getAttribute('data-mw-amount'),'100');await page.locator('[data-mw-view="A-71"]').click();assert.equal(await page.locator('[data-mw-row="A-71|2|0"]').getAttribute('data-mw-amount'),'100');assert.equal(await page.evaluate(()=>JSON.stringify(ACCOUNT_ROWS)),raw);assert.deepEqual(errors,[]);await context.close();}finally{await browser.close();}});
test('equal unlinked debit and credit still block; invalid or unbalanced source cannot proceed', {skip:!executablePath&&'Set CHROMIUM_PATH'},async()=>{const browser=await chromium.launch({executablePath,args:['--no-sandbox','--disable-dev-shm-usage']});try{const cancelled=[...ledger.slice(0,3),{'نوع سند':'ابتدای سال','کد حساب کل':'30','عنوان حساب کل':'حساب دیگر','بدهکار':'50','بستانکار':''},{'نوع سند':'ابتدای سال','کد حساب کل':'40','عنوان حساب کل':'حساب مقابل','بدهکار':'','بستانکار':'50'}];let {page,context,errors}=await setup(browser,cancelled);await assign(page,'10','A-70|1|5');await assign(page,'20','A-71|2|0');assert(await page.locator('#mwMapFinish').isDisabled());assert.match(await page.locator('#mwMapProgress').innerText(),/۲ حساب باقی/);assert.deepEqual(errors,[]);await context.close();({page,context,errors}=await setup(browser,ledger.slice(0,2)));await assign(page,'10','A-70|1|5');assert(await page.locator('#mwMapFinish').isDisabled());assert.match(await page.locator('#mwMapError').innerText(),/تراز نیست/);assert.equal(await page.locator('#mwPreview').count(),0);assert.deepEqual(errors,[]);await context.close();const invalid=[...ledger,{'نوع سند':'ابتدای سال','کد حساب کل':'','عنوان حساب کل':'بدون کد','بدهکار':'0','بستانکار':''}];({page,context,errors}=await setup(browser,invalid));await assign(page,'10','A-70|1|5');await assign(page,'20','A-71|2|0');await assign(page,'30','A-70|1|3');assert(await page.locator('#mwMapFinish').isDisabled());assert.match(await page.locator('#mwMapError').innerText(),/فاقد کد کل/);assert.deepEqual(errors,[]);await context.close();}finally{await browser.close();}});
test('GL mappings affect every minor, classification, A and print; review changes remain explicit', {skip:!executablePath&&'Set CHROMIUM_PATH'},async()=>{const browser=await chromium.launch({executablePath,args:['--no-sandbox','--disable-dev-shm-usage']});try{const {page,context,errors}=await setup(browser,ledger);await complete(page);await page.locator('#mwClassOpen').click();await choose(page,'source','10','11');await choose(page,'destination','20','21');await page.locator('[name=amount]').fill('20');await page.locator('[name=description]').fill('ثبت آزمایشی');await page.locator('#mwClassForm button[type=submit]').click();assert.equal(await page.locator('[data-class-delete]').count(),1);await page.locator('[data-mw-view="A-70"]').click();let cash=page.locator('[data-mw-row="A-70|1|5"]');assert.equal((await cash.locator('[data-mw-calc-col="4"]').innerText()).trim(),'۲۰');assert.equal((await cash.locator('[data-mw-calc-col="5"]').innerText()).trim(),'۸۰');await page.locator('#mwMapReview').click();assert.equal(await page.locator('#mwPreview').count(),0);await page.locator('[data-map-major="10"]').click();await page.locator('#mwMapDestination').selectOption('A-70|1|3');page.once('dialog',d=>d.dismiss());await page.locator('#mwMapSave').click();assert.equal(await page.locator('#mwMapDestination').inputValue(),'A-70|1|3');page.once('dialog',d=>d.accept());await page.locator('#mwMapSave').click();await page.locator('#mwMapFinish').click();await page.locator('[data-mw-view="A-70"]').click();const newTopic=page.locator('[data-mw-row="A-70|1|3"]');assert.equal(await newTopic.getAttribute('data-mw-amount'),'100');assert.equal((await newTopic.locator('[data-mw-calc-col="4"]').innerText()).trim(),'۲۰');assert.equal((await newTopic.locator('[data-mw-calc-col="5"]').innerText()).trim(),'۸۰');cash=page.locator('[data-mw-row="A-70|1|5"]');assert.equal(await cash.count(),0);await page.evaluate(()=>{window.print=()=>{};});await page.locator('#mwPrint').click();await page.emulateMedia({media:'print'});assert.equal((await page.locator('#printHost [data-mw-row="A-70|1|3"] [data-mw-calc-col="5"]').innerText()).trim(),'۸۰');assert((await require('pdf-lib').PDFDocument.load(await page.pdf({format:'A4',landscape:true,printBackground:true}))).getPageCount()>0);assert.deepEqual(errors,[]);await context.close();}finally{await browser.close();}});
test('wizard keeps unconfirmed edits safe, paginates large GL lists and works on short dark mobile', {skip:!executablePath&&'Set CHROMIUM_PATH'},async()=>{const browser=await chromium.launch({executablePath,args:['--no-sandbox','--disable-dev-shm-usage']});try{const many=Array.from({length:76},(_,i)=>({'نوع سند':'ابتدای سال','کد حساب کل':String(i+1),'عنوان حساب کل':'عنوان مشترک','بدهکار':'0','بستانکار':''})),{page,context,errors}=await setup(browser,many,{width:320,height:580});await page.evaluate(()=>applyTheme('dark'));await page.locator('#mwMapSearch').fill('76');assert.equal(await page.locator('[data-map-major]').count(),1);await page.locator('[data-map-major="76"]').click();await page.locator('#mwMapDestination').selectOption('A-70|1|5');await page.locator('#mwMapSearch').fill('');page.once('dialog',d=>d.dismiss());await page.locator('[data-map-major="1"]').click();assert.match(await page.locator('#mwMapAccount h2').innerText(),/۷۶/);await page.locator('#mwMapSave').click();assert.match(await page.locator('#mwMapProgress').innerText(),/۱ از ۷۶/);await page.locator('#mwMapNextPage').click();await page.locator('#mwMapNextPage').click();assert.equal(await page.locator('[data-map-major]').count(),5);assert.equal(await page.locator('[data-map-major="76"]').count(),0);await page.locator('#mwMapFilter').selectOption('linked');assert.match(await page.locator('[data-map-major="76"]').innerText(),/متصل‌شده/);assert(await page.locator('#mwMapFinish').isDisabled());assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);assert.deepEqual(errors,[]);await context.close();}finally{await browser.close();}});
test('linked A topic cannot be hidden; removed empty topic can be restored by GL mapping', {skip:!executablePath&&'Set CHROMIUM_PATH'},async()=>{const browser=await chromium.launch({executablePath,args:['--no-sandbox','--disable-dev-shm-usage']});try{const {page,context,errors}=await setup(browser,ledger);await complete(page);await page.locator('[data-mw-view="A-70"]').click();let message='';page.once('dialog',d=>{message=d.message();d.accept();});await page.locator('[data-mw-topic-remove="A-70|1|5"]').click();assert.match(message,/۱۰.*موجودی نقد/);assert.equal(await page.locator('[data-mw-row="A-70|1|5"]').getAttribute('data-mw-amount'),'100');await page.locator('.mw-preview-tools details summary').filter({hasText:'بازگردانی سرفصل'}).click();await page.locator('[data-mw-topic-restore="A-70|0|0"]').click();page.once('dialog',d=>d.accept());await page.locator('[data-mw-topic-remove="A-70|0|0"]').click();assert.equal(await page.locator('[data-mw-row="A-70|0|0"]').count(),0);await page.locator('#mwMapReview').click();await assign(page,'10','A-70|0|0');await page.locator('#mwMapFinish').click();await page.locator('[data-mw-view="A-70"]').click();assert.equal(await page.locator('[data-mw-row="A-70|0|0"]').getAttribute('data-mw-amount'),'100');assert.deepEqual(errors,[]);await context.close();}finally{await browser.close();}});
