test('detail-level transfer follows the mapping of its GL and appears once in A', {skip:!executablePath&&'Set CHROMIUM_PATH'},async()=>{const browser=await chromium.launch({executablePath,args:['--no-sandbox','--disable-dev-shm-usage']});try{const data=[{'نوع سند':'ابتدای سال','کد حساب کل':'10','عنوان حساب کل':'نقد','کد حساب معین':'11','عنوان حساب معین':'بانک','کد حساب تفصیلی':'1','عنوان حساب تفصیلی':'شخص الف','بدهکار':'60','بستانکار':''},{'نوع سند':'ابتدای سال','کد حساب کل':'10','عنوان حساب کل':'نقد','کد حساب معین':'11','عنوان حساب معین':'بانک','کد حساب تفصیلی':'2','عنوان حساب تفصیلی':'شخص ب','بدهکار':'40','بستانکار':''},ledger[2]];const {page,context,errors}=await setup(browser,data);await assign(page,'10','A-70|1|5');await assign(page,'20','A-71|2|0');await page.locator('#mwMapFinish').click();await page.locator('#mwClassOpen').click();await page.locator('[data-class-open="source"]').click();await page.locator('#mwClassDialog [data-class-clear]').click();await page.locator(`#mwClassDialog [data-class-row-expand='${JSON.stringify(['hier',[0,'10']])}']`).dblclick();await page.locator(`#mwClassDialog [data-class-row-expand='${JSON.stringify(['10','11'])}']`).dblclick();await page.locator(`#mwClassDialog [data-class-select='${JSON.stringify(['hier',[0,'10'],[1,'11'],[2,'1']])}']`).check();await page.locator('#mwClassDialog [data-class-confirm]').click();await choose(page,'destination','20','21');await page.locator('[name=amount]').fill('20');await page.locator('[name=description]').fill('انتقال تفصیلی');await page.locator('#mwClassForm button[type=submit]').click();assert.equal(await page.locator('[data-class-delete]').count(),1);await page.locator('[data-mw-view="A-70"]').click();const row=page.locator('[data-mw-row="A-70|1|5"]');assert.equal(await row.getAttribute('data-mw-amount'),'100');assert.equal((await row.locator('[data-mw-calc-col="4"]').innerText()).trim(),'۲۰');assert.equal((await row.locator('[data-mw-calc-col="5"]').innerText()).trim(),'۸۰');assert.deepEqual(errors,[]);await context.close();}finally{await browser.close();}});
test('rename and custom A-72 heading preserve links, print, and subtotal placement, with unused headings hidden and restorable', {skip:!executablePath&&'Set CHROMIUM_PATH'},async()=>{const browser=await chromium.launch({executablePath,args:['--no-sandbox','--disable-dev-shm-usage']});try{const data=[{'نوع سند':'ابتدای سال','کد حساب کل':'10','عنوان حساب کل':'درآمد فروش','کد حساب معین':'11','عنوان حساب معین':'فروش الف','بدهکار':'','بستانکار':'100'},{'نوع سند':'ابتدای سال','کد حساب کل':'20','عنوان حساب کل':'هزینه','کد حساب معین':'21','عنوان حساب معین':'هزینه الف','بدهکار':'100','بستانکار':''}];const {page,context,errors}=await setup(browser,data,{width:390,height:844});const raw=await page.evaluate(()=>JSON.stringify(ACCOUNT_ROWS));await page.locator('#mwMapDestination').selectOption('A-72|0|0');await page.locator('.mw-map-topic-edit summary').click();await page.locator('#mwMapTopicName').fill('درآمد خدمات ویژه');await page.locator('#mwMapRename').click();assert.equal(await page.locator('#mwMapDestination').inputValue(),'A-72|0|0');assert.match(await page.locator('#mwMapDestination option:checked').innerText(),/درآمد خدمات ویژه/);await page.locator('#mwMapSave').click();await page.locator('.mw-map-custom summary').click();await page.locator('#mwMapCustomGroup').selectOption('A-72|0');await page.locator('#mwMapCustomAfter').selectOption('1');await page.locator('#mwMapCustomName').fill('هزینه ویژه');await page.locator('#mwMapCustomAdd').click();assert.equal(await page.locator('#mwMapDestination').inputValue(),'A-72|custom|1');assert.match(await page.locator('#mwMapProgress').innerText(),/۱ از ۲/);await page.locator('#mwMapSave').click();await page.locator('#mwMapFinish').click();await page.locator('[data-mw-view="A-72"]').click();let row=page.locator('[data-mw-row="A-72|0|0"]');assert.match(await row.innerText(),/درآمد خدمات ویژه/);assert.equal(await row.getAttribute('data-mw-amount'),'100');row=page.locator('[data-mw-row="A-72|custom|1"]');assert.match(await row.innerText(),/هزینه ویژه/);assert.equal(await row.getAttribute('data-mw-amount'),'-100');assert.equal(await page.locator('[data-mw-row="A-72|0|2"]').count(),0);const gross=page.locator('[data-mw-row="total:A-72:1"]');assert.equal(await gross.getAttribute('data-mw-amount'),'0');assert.equal(await page.evaluate(()=>JSON.stringify(ACCOUNT_ROWS)),raw);
 await page.locator('.mw-preview-tools details summary').filter({hasText:'بازگردانی سرفصل'}).click();await page.locator('[data-mw-topic-restore="A-72|0|2"]').click();assert.equal(await page.locator('[data-mw-row="A-72|0|2"]').count(),1);await page.evaluate(()=>{window.print=()=>{}});await page.locator('#mwPrint').click();await page.emulateMedia({media:'print'});assert.match(await page.locator('#printHost [data-mw-row="A-72|0|0"]').innerText(),/درآمد خدمات ویژه/);assert.match(await page.locator('#printHost [data-mw-row="A-72|custom|1"]').innerText(),/هزینه ویژه/);await page.emulateMedia({media:'screen'});await page.locator('#mwMapReview').click();await page.locator('[data-map-major="10"]').click();assert.match(await page.locator('#mwMapTopicName').inputValue(),/درآمد خدمات ویژه/);await page.locator('#mwMapFinish').click();await page.locator('[data-mw-view="A-72"]').click();assert.equal(await page.locator('#mwPreview [data-mw-row="A-72|0|2"]').count(),1,'explicitly restored rows survive review');assert.deepEqual(errors,[]);await context.close();}finally{await browser.close();}});
