test('two-line frames and enlarged audit-control rows fit every main-family workpaper and actual PDF', {skip:!executablePath&&'Set CHROMIUM_PATH'},async()=>{const browser=await chromium.launch({executablePath,args:['--no-sandbox','--disable-dev-shm-usage']});try{const data=Array.from({length:36},(_,i)=>({'نوع سند':'ابتدای سال','کد حساب کل':'10','عنوان حساب کل':'دارایی ثابت مشهود','کد حساب معین':String(i+1),'عنوان حساب معین':'دارایی '+(i+1),'بدهکار':'1','بستانکار':''}));data.push({'نوع سند':'ابتدای سال','کد حساب کل':'20','عنوان حساب کل':'بدهی','کد حساب معین':'21','عنوان حساب معین':'بدهی','بدهکار':'','بستانکار':'36'});const {page,context,errors}=await setup(browser,data,{width:1280,height:900});await assign(page,'10','A-70|0|0');await assign(page,'20','A-71|2|0');await page.locator('#mwMapFinish').click();await page.evaluate(()=>document.fonts.ready);
 async function check(root){const results=await page.locator(root+' .mw-paper').evaluateAll(pages=>pages.map((p,i)=>{const o=p.querySelector('.mw-outer'),inn=p.querySelector('.mw-inside'),c=p.querySelector('.mw-card'),ctl=p.querySelector('.mw-controls'),title=p.querySelector('.mw-control-title'),items=[...p.querySelectorAll('.mw-control-items > div')],r=c.getBoundingClientRect();return {outer:getComputedStyle(o).borderTopWidth,middle:getComputedStyle(inn).borderTopWidth,inner:getComputedStyle(c).borderTopWidth,cardFits:c.scrollHeight<=c.clientHeight+1&&inn.scrollHeight<=inn.clientHeight+1,hasControl:!!ctl,height:title?.getBoundingClientRect().height||0,titleFont:parseFloat(title?getComputedStyle(title).fontSize:'0'),itemFont:parseFloat(items[0]?getComputedStyle(items[0].parentElement).fontSize:'0'),contentFits:items.every(el=>{const box=el.getBoundingClientRect(),range=document.createRange();range.selectNodeContents(el);return [...range.getClientRects()].every(x=>x.left>=box.left-1&&x.right<=box.right+1&&x.top>=box.top-1&&x.bottom<=box.bottom+1)&&box.bottom<=r.bottom+1;})};}));assert(results.length);for(const [i,r] of results.entries()){assert(parseFloat(r.outer)>0&&parseFloat(r.middle)===0&&parseFloat(r.inner)>0,JSON.stringify(r));assert(r.cardFits,JSON.stringify(r));assert.equal(r.hasControl,i===results.length-1);if(r.hasControl){assert(r.height>=24&&r.titleFont>=14&&r.itemFont>=14,JSON.stringify(r));assert(r.contentFits,JSON.stringify(r));}}return results.length;}
 for(const [view,code] of [['accounts','10'],['asset-analysis','10'],['A-70',''],['A-71',''],['A-72',''],['A-73',''],['classification','']]){if(view==='classification')await page.locator('#mwClassOpen').click();else await page.locator(`[data-mw-view="${view}"]${code?`[data-mw-active="${code}"]`:''}`).click();const count=await check('#mwPreview');assert(await page.locator('#mwPrint').isEnabled(),`${view}: print should fit`);await page.evaluate(()=>window.print=()=>{});await page.locator('#mwPrint').click();await page.emulateMedia({media:'print'});assert.equal(await check('#printHost'),count);const pdf=await page.pdf({format:'A4',landscape:true,printBackground:true});assert.equal((await require('pdf-lib').PDFDocument.load(pdf)).getPageCount(),count,view);await page.emulateMedia({media:'screen'});await page.evaluate(()=>window.__activePrintRestore?.());}
assert.deepEqual(errors,[]);await context.close();}finally{await browser.close();}});
