test('drag and keyboard change row groups only on the active workpaper and survive print', {skip:!executablePath&&'Set CHROMIUM_PATH'},async()=>{const browser=await chromium.launch({executablePath,args:['--no-sandbox','--disable-dev-shm-usage']});try{const {page,context,errors}=await setup(browser,ledger,{width:1366,height:768});await complete(page);await page.locator('[data-mw-view="A-70"]').click();let handle=page.locator('#mwPreview [data-mw-row-resize="title"]').first();await handle.evaluate(el=>el.scrollIntoView({block:'center',inline:'center'}));let box=await handle.boundingBox();await page.mouse.move(box.x+box.width/2,box.y+box.height/2);await page.mouse.down();await page.mouse.move(box.x+box.width/2,box.y+box.height/2+22,{steps:4});await page.mouse.up();const title=Number(await page.locator('#mwTitleRowHeight').inputValue());assert(title>=10,`height after drag: ${title}, handle ${JSON.stringify(box)}`);await page.locator('#mwPreview [data-mw-row-resize="total"]').first().focus();await page.keyboard.press('ArrowDown');const total=Number(await page.locator('#mwTotalRowHeight').inputValue());assert(total>0);await page.locator('#mwTotalRowHeight').fill('14');await page.locator('#mwApplyHeights').click();const actual=await page.locator('#mwPreview .mw-paper-table tbody tr').evaluateAll(rows=>rows.map(r=>({total:r.classList.contains('mw-total'),height:r.getBoundingClientRect().height})));assert(actual.filter(r=>r.total).length>=2);assert(actual.filter(r=>r.total).every(r=>r.height>=14*96/25.4-1));assert(actual.filter(r=>!r.total).every(r=>r.height>=title*96/25.4-1));await page.locator('[data-mw-view="A-71"]').click();assert.equal(await page.locator('#mwTitleRowHeight').inputValue(),'');assert.equal(await page.locator('#mwTotalRowHeight').inputValue(),'');await page.locator('#mwTitleRowHeight').fill('8');await page.locator('#mwApplyHeights').click();await page.locator('[data-mw-view="A-70"]').click();assert.equal(Number(await page.locator('#mwTitleRowHeight').inputValue()),title);assert.equal(await page.locator('#mwTotalRowHeight').inputValue(),'14');await page.evaluate(()=>window.print=()=>{});await page.locator('#mwPrint').click();assert.equal(await page.locator('#printHost .mw-row-resize').count(),0);assert(await page.locator('#printHost .mw-paper').evaluateAll(p=>p.every(x=>x.style.getPropertyValue('--mw-user-total-row')==='14mm')));await page.emulateMedia({media:'print'});assert((await require('pdf-lib').PDFDocument.load(await page.pdf({format:'A4',landscape:true,printBackground:true}))).getPageCount()>0);assert.deepEqual(errors,[]);await context.close();}finally{await browser.close();}});

test('excluding an opening balance preserves its standalone sheet and warns of the comparative gap', {skip:!executablePath&&'Set CHROMIUM_PATH'},async()=>{const browser=await chromium.launch({executablePath,args:['--no-sandbox','--disable-dev-shm-usage']});try{const data=[{'نوع سند':'ابتدای سال','کد حساب کل':'10','عنوان حساب کل':'نقد','کد حساب معین':'11','عنوان حساب معین':'بانک','بدهکار':'100','بستانکار':''},{'نوع سند':'ابتدای سال','کد حساب کل':'20','عنوان حساب کل':'بدهی','کد حساب معین':'21','عنوان حساب معین':'پرداختنی','بدهکار':'','بستانکار':'100'}];const {page,context,errors}=await setup(browser,data);const before=await page.evaluate(()=>JSON.stringify(ACCOUNT_ROWS));await assign(page,'10','A-70|1|5');page.once('dialog',d=>d.accept());await page.locator('[data-map-remove="20"]').click();await page.locator('#mwMapFinish').click();await page.locator('[data-mw-view="accounts"][data-mw-active="20"]').click();assert.equal((await page.locator('[data-mw-row="total:جمع حساب کل بدهی"] [data-mw-calc-col="6"]').innerText()).trim(),'(۱۰۰)');await page.locator('[data-mw-view="A-70"]').click();assert.equal((await page.locator('[data-mw-row="total:جمع کل"] [data-mw-calc-col="6"]').innerText()).trim(),'۱۰۰');assert.match(await page.locator('.mw-prior-balance-warning').innerText(),/۱۰۰ ریال/);await page.locator('#mwClassOpen').click();await page.locator('[data-class-open="source"]').click();assert.equal(await page.locator('#mwClassDialog').getByText('بدهی',{exact:false}).count(),0);await page.keyboard.press('Escape');await page.locator('#mwMapReview').click();await page.locator('[data-map-bar-restore="20"]').click();await assign(page,'20','A-71|2|0');await page.locator('#mwMapFinish').click();await page.locator('[data-mw-view="A-71"]').click();assert.equal((await page.locator('[data-mw-row="total:جمع کل"] [data-mw-calc-col="6"]').innerText()).trim(),'۱۰۰');assert.equal(await page.locator('.mw-prior-balance-warning').count(),0);assert.equal(await page.evaluate(()=>JSON.stringify(ACCOUNT_ROWS)),before);assert.deepEqual(errors,[]);await context.close();}finally{await browser.close();}});
